;(function(){
// 랜딩(`ScaleToFitWidth.tsx`)과 같은 방식 — 데모는 940px 기준으로 그려져 있고,
  // 칸 폭에 맞춰 통째로 축소한다. 줄어든 만큼의 높이를 바깥 칸에 예약해 둔다.
  (function(){
    // 카드 데모는 평소엔 결과 화면으로 멈춰 있고, 커서를 올린 동안만 움직인다.
    document.querySelectorAll('.card.demo').forEach(function(card){
      var frame = card.querySelector('.card-demo iframe');
      if (!frame || card.querySelector('[data-no-hover]')) return;
      var doc = frame.getAttribute('srcdoc');
      function reload(play){ frame.name = play ? 'play' : ''; frame.srcdoc = doc; }
      card.addEventListener('mouseenter', function(){ reload(true); });
      card.addEventListener('mouseleave', function(){ reload(false); });
    });
  })();
  (function(){
    document.querySelectorAll('[data-demo-fit]').forEach(function(box){
      var frame = box.querySelector('iframe');
      if (!frame) return;
      var designW = Number(box.dataset.demoW) || 940;
      var fixed = box.hasAttribute('data-fixed');
      function fit(){
        var w = box.clientWidth;
        if (!w) return;
        var scale = w / designW;
        frame.style.transform = 'scale(' + scale + ')';
        if (!fixed) box.style.height = (frame.offsetHeight * scale) + 'px';
      }
      fit();
      new ResizeObserver(fit).observe(box);
    });
  })();
})();
